INSERT INTO question_papers (id, slug, title, exam_type, focus_tags, question_count, difficulty, is_premium, sort_order, time_limit_minutes)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('9d40d600-94bb-42ae-a473-343eacb5a0d3', '46c4ee26-e59e-430d-8361-a596e940e481', 0, 'A WAF rate-based rule, which tracks the request rate from each individual IP address over a rolling time window and automatically blocks (or applies another configured action to) any IP that exceeds a defined request-count threshold.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('335d53a7-7307-4cec-8210-940e4385d9b1', '46c4ee26-e59e-430d-8361-a596e940e481', 1, 'A standard IP-match WAF rule, since IP-match rules automatically throttle any IP once it exceeds a request-rate threshold with no additional configuration.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dd50d8f1-8448-44c5-9739-93603f2bb627', '46c4ee26-e59e-430d-8361-a596e940e481', 2, 'AWS KMS, since KMS is responsible for throttling excessive request rates from a specific IP address.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d9cf9178-6a77-4a9c-b1b7-d11d6cd883d1', '46c4ee26-e59e-430d-8361-a596e940e481', 3, 'WAF has no capability to track or limit request rate from a specific source; only total account-wide throughput can be limited.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e80513f8-96a7-41d0-be7c-36750f521781', '85dc2347-a4a5-449c-9dc4-5d0331f4f714', 0, 'An IAM permissions boundary, attached to the roles the team leads create, which sets the maximum permissions that role can ever have — even if the team lead attaches a broader permissions policy to the role, the EFFECTIVE permissions are the intersection of the attached policy and the permissions boundary, never exceeding the boundary.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('340f31d4-c0a5-42d8-ab66-dd9e49ceed0e', '85dc2347-a4a5-449c-9dc4-5d0331f4f714', 1, 'A resource-based policy, since resource-based policies are what cap the maximum permissions an IAM role can ever have.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a0863e7f-c43b-45a5-bf3d-ca8f7d9a5473', '85dc2347-a4a5-449c-9dc4-5d0331f4f714', 2, 'Security Groups, since Security Groups enforce maximum IAM permission ceilings for roles.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6003b162-5475-4ad9-8a4b-1224251edcde', '85dc2347-a4a5-449c-9dc4-5d0331f4f714', 3, 'This kind of delegated, capped permission-granting is not achievable through any IAM feature.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cf5582f5-8806-44e8-aac1-541c7e5c41c0', 'c15a8b55-cef0-42a4-96f9-ffc5bdd80f8a', 0, 'An Interface Endpoint provisions an actual elastic network interface (ENI) with a private IP address directly inside the VPC''s subnet, which the application connects to (optionally via a Route 53 private hosted zone alias for the target service''s normal DNS name) — unlike a Gateway Endpoint, which works by adding a route table entry rather than placing an ENI in the subnet, and is limited to only S3 and DynamoDB as targets.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('23aef61c-75bf-4de4-84a2-e6e49b3e3af9', 'c15a8b55-cef0-42a4-96f9-ffc5bdd80f8a', 1, 'Interface Endpoints and Gateway Endpoints are fully identical in mechanism, with no technical distinction between them whatsoever.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6b69d3a4-976a-4014-b6de-2e06f101c489', 'c15a8b55-cef0-42a4-96f9-ffc5bdd80f8a', 2, 'An Interface Endpoint can only ever be used for S3 and DynamoDB, while a Gateway Endpoint supports every AWS service and third-party SaaS integration.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('aa77088f-82cc-4d16-bfc6-80f145cbbe2d', 'c15a8b55-cef0-42a4-96f9-ffc5bdd80f8a', 3, 'VPC endpoints of any kind cannot be used to reach third-party SaaS services under any configuration.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('efc011a1-eaf8-4f06-9d73-fbe655191186', '760df109-289c-4139-b3ad-a3755df2dc21', 0, 'S3 Object Lock, in Compliance mode, which prevents an object version from being deleted or overwritten for a specified retention period (or indefinitely, via a legal hold) — in Compliance mode specifically, not even the root user can remove or shorten the protection before the retention period expires, satisfying strict regulatory WORM requirements.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('be355cf7-fe42-49fc-9d71-466edeee2a03', '760df109-289c-4139-b3ad-a3755df2dc21', 1, 'S3 Versioning alone, since Versioning by itself makes every object version permanently undeletable by any party including the root user.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('83c433ea-9abb-4fa0-9a7e-c225783f9197', '760df109-289c-4139-b3ad-a3755df2dc21', 2, 'S3 Transfer Acceleration, since Transfer Acceleration is the feature responsible for WORM compliance retention.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('45823a00-2f2b-49d7-9d31-05c60eed0984', '760df109-289c-4139-b3ad-a3755df2dc21', 3, 'S3 has no mechanism to prevent deletion by the account root user under any configuration.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ba21b73e-5c0d-45a4-9252-688b27006989', '6ecb9d3e-72ae-4b77-8e8d-e0a2d400d6f2', 0, 'AWS Shield Advanced, a paid, opt-in service tier providing enhanced DDoS protection, direct access to the AWS DDoS Response Team during active attacks, cost protection against attack-driven scaling charges, and detailed real-time attack visibility and reporting — a substantially higher tier than the free, automatically-included Shield Standard.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('05315167-c464-4c2a-aef7-b59a45df72da', '6ecb9d3e-72ae-4b77-8e8d-e0a2d400d6f2', 1, 'AWS Shield Standard, since Shield Standard already includes DRT access, cost protection, and detailed attack reporting for every AWS customer automatically at no charge.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('11fc7af9-97aa-456d-962a-9981208d9607', '6ecb9d3e-72ae-4b77-8e8d-e0a2d400d6f2', 2, 'AWS WAF alone, since WAF''s core function is providing DDoS Response Team access and attack-driven cost protection.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cb976579-18c4-46e5-b8da-1771947a3231', '6ecb9d3e-72ae-4b77-8e8d-e0a2d400d6f2', 3, 'No AWS service provides direct human DDoS response team access under any paid or free tier.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4e5900e3-a3e9-410d-a4a7-35e833b46c71', '47594ee9-2847-4c99-8d9d-c311671a4e45', 0, 'Amazon Macie, a managed service that uses machine learning and pattern matching to automatically discover, classify, and report on sensitive data (like PII, financial data, or credentials) stored in S3, at a scale impractical for manual review.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fece3501-cf22-421d-b956-7f145a2cd16c', '47594ee9-2847-4c99-8d9d-c311671a4e45', 1, 'AWS Config, since Config''s core function is scanning S3 object content for PII and sensitive data patterns.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5f4fd2f4-d9f7-4f39-b2c0-c81e223e94c2', '47594ee9-2847-4c99-8d9d-c311671a4e45', 2, 'Amazon GuardDuty, since GuardDuty''s primary function is classifying sensitive data content within S3 objects.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('65dabe83-c02d-47c7-8c2d-3cd0f1043727', '47594ee9-2847-4c99-8d9d-c311671a4e45', 3, 'No AWS service can automatically discover or classify sensitive data within S3 objects; only fully manual review is possible.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6a2125ca-c52e-45b5-a492-6508f478f576', '71495380-6956-4feb-9622-7d9fd90b6843', 0, 'Multi-Value Answer routing, which returns up to 8 healthy, randomly-selected records in response to a DNS query (automatically excluding any record whose associated health check is currently failing), providing basic multi-target availability and rudimentary load distribution without the complexity of weighted or latency-based routing.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a6a47639-979a-44c5-ba43-0dd0f1df3597', '71495380-6956-4feb-9622-7d9fd90b6843', 1, 'Simple routing, since Simple routing is specifically designed to return multiple health-checked values with automatic unhealthy-record exclusion.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c81437c4-a65f-4890-b577-4070ebe867a2', '71495380-6956-4feb-9622-7d9fd90b6843', 2, 'Geolocation routing, since Geolocation routing''s primary function is returning multiple randomly-selected, health-checked IP addresses per query.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c5498e4f-bc81-4a18-875d-1eb782ced899', '71495380-6956-4feb-9622-7d9fd90b6843', 3, 'Route 53 can only ever return exactly one IP address per query under any routing policy.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1bd3b9c4-ca65-4dd6-8b49-a59ddcfb8778', '658948b1-d935-4976-9201-02f723dbb530', 0, 'A Dead Letter Queue (DLQ) — configured with a maxReceiveCount threshold, after which a message that has failed processing that many times is automatically moved to a separate DLQ instead of being redelivered again, isolating problematic messages for separate investigation without them continuing to consume normal processing capacity indefinitely.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1d833646-7df0-4682-a60d-3ce48cf5a3b4', '658948b1-d935-4976-9201-02f723dbb530', 1, 'SQS has no mechanism to isolate repeatedly-failing messages; every message is redelivered an unlimited number of times forever with no alternative.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1d5a8460-8f41-4b0d-b330-aefed949ede9', '658948b1-d935-4976-9201-02f723dbb530', 2, 'DynamoDB Global Tables, since Global Tables are the SQS feature responsible for isolating repeatedly-failing messages.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('dd7186ec-4d11-4a00-aed8-82b4f5a9ab5f', '658948b1-d935-4976-9201-02f723dbb530', 3, 'S3 Object Lock, since Object Lock''s core function is isolating failed SQS message deliveries.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c1d78989-52e6-4552-81bd-599b3d4b4cd0', '351d71bd-e172-4e39-9aae-f6e5e071a05f', 0, 'AWS Elastic Beanstalk, a managed platform-as-a-service that automatically provisions and manages the underlying infrastructure — EC2 instances, load balancer, Auto Scaling Group, health monitoring — for a deployed application, based on the application code and a chosen platform/runtime, while still giving the developer access to and control over the underlying resources if needed.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b6831fa8-d587-4825-a473-7230bc69e348', '351d71bd-e172-4e39-9aae-f6e5e071a05f', 1, 'AWS Direct Connect, since Direct Connect automatically provisions load balancing, auto scaling, and health monitoring for deployed applications.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c5c3838b-1912-4386-9342-3469e87afc6a', '351d71bd-e172-4e39-9aae-f6e5e071a05f', 2, 'Amazon Macie, since Macie''s core function is automatically provisioning application infrastructure and health monitoring.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e367e178-9f49-447e-a1b6-ba7365183103', '351d71bd-e172-4e39-9aae-f6e5e071a05f', 3, 'There is no way to have AWS automatically manage this combination of infrastructure; every piece must always be manually configured separately.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b42aadbb-2f7b-4dc5-9864-48d26ae8b52e', '1e9da3c0-85c2-498a-8ec6-9ea6c0a6c5ff', 0, 'CRR replication is asynchronous, meaning there is normally a replication delay (typically seconds, but not instantaneous or guaranteed-zero) between an object being written to the source bucket and it becoming available in the destination bucket — this delay directly determines the realistic minimum achievable RPO; a shorter RPO requirement may need CRR''s optional replication-time control feature, which provides a predictable replication window with monitoring.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('1fa0b241-13f6-432e-b386-6a068f692b46', '1e9da3c0-85c2-498a-8ec6-9ea6c0a6c5ff', 1, 'CRR replication is perfectly synchronous with zero possible delay, so RPO is always effectively zero regardless of any other factor.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('b4d0f0f6-0d95-4471-a8ab-705a354a0e3c', '1e9da3c0-85c2-498a-8ec6-9ea6c0a6c5ff', 2, 'CRR has no relationship to RPO calculations of any kind, since replication delay is never a relevant factor for disaster recovery planning.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('289cef04-15da-4f80-8a99-be81fca80c63', '1e9da3c0-85c2-498a-8ec6-9ea6c0a6c5ff', 3, 'CRR only replicates data once per calendar month, making it unsuitable for any RPO calculation shorter than 30 days.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4c244799-6c2f-4c1a-9c0f-ffb16923c2eb', '729fb6a1-e505-4a77-9cea-78409818fe79', 0, 'The ALB''s idle timeout setting (how long the load balancer keeps a connection open with no data flowing before closing it) should be increased to comfortably exceed the backend''s actual maximum expected response time for its slowest legitimate requests, rather than left at a default value that happens to be shorter than genuine processing time.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('d53f5b71-7538-4f70-9844-fd0768dc85ea', '729fb6a1-e505-4a77-9cea-78409818fe79', 1, 'ALB idle timeout is a fixed, non-configurable value that can never be changed under any circumstance.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5f367fb9-3987-4c19-82f7-9a5ab389f201', '729fb6a1-e505-4a77-9cea-78409818fe79', 2, 'The correct fix is to decrease the idle timeout to as close to zero as possible, since a shorter timeout always resolves premature connection closures.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('31ccf0a3-aa29-4699-82fc-b7133ddaeb51', '729fb6a1-e505-4a77-9cea-78409818fe79', 3, 'Idle timeout only affects NLBs, never ALBs, so this setting is irrelevant to the scenario described.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c6ff76fc-4dc7-4e22-b56c-be7895a567c0', '97437709-2fdc-4296-9396-c33bb88978fa', 0, 'CloudFront Origin Shield, an additional caching layer sitting between the standard edge locations and the origin, which consolidates cache-miss requests from multiple edge locations into fewer requests actually reaching the origin, reducing redundant origin load and improving cache hit ratio for the origin''s perspective.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bfd23213-a364-4806-bc26-d2dc2e6ee2da', '97437709-2fdc-4296-9396-c33bb88978fa', 1, 'AWS Global Accelerator, since Global Accelerator''s core function is consolidating CloudFront cache-miss requests before they reach the origin.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0365b384-8ed2-4ca0-be35-8dbf325540a7', '97437709-2fdc-4296-9396-c33bb88978fa', 2, 'S3 Transfer Acceleration, since Transfer Acceleration consolidates CloudFront-to-origin cache-miss traffic.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5c284c77-9aab-407b-bcf8-f1a4c3042630', '97437709-2fdc-4296-9396-c33bb88978fa', 3, 'CloudFront has no feature to reduce redundant origin requests from independent cache misses across edge locations.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('994391ca-6fa0-453e-9eed-a816ad2cdd9b', '8c85a2de-3df1-4344-a14f-1f21c840c95a', 0, 'Amazon MQ, a managed message broker service supporting industry-standard protocols like JMS, AMQP, MQTT, and STOMP (via ActiveMQ or RabbitMQ engines), specifically designed for migrating existing applications that rely on these standard protocols without needing to rewrite the application''s messaging integration code.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7e1a061d-a559-4691-8074-249f6eea7fc0', '8c85a2de-3df1-4344-a14f-1f21c840c95a', 1, 'Amazon SQS, since SQS natively supports the JMS protocol with zero application code changes required for any JMS-based application.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fc69988c-d6f4-4208-a341-a3610084bc15', '8c85a2de-3df1-4344-a14f-1f21c840c95a', 2, 'Amazon Kinesis Data Streams, since Kinesis is the AWS service specifically designed for JMS protocol compatibility.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('7d5f922b-b5b0-40b5-8d54-2726a1a11821', '8c85a2de-3df1-4344-a14f-1f21c840c95a', 3, 'No AWS service supports industry-standard messaging protocols like JMS; full application rewrite is always required.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0cc97dff-1bfe-4164-98fa-0db616e5957d', 'd5517e04-dbf1-44bf-9144-ab2033d7f190', 0, 'Aurora Serverless (v2), which automatically and rapidly scales database compute capacity up or down based on actual load in fine-grained increments, without manual instance-size changes, and scales capacity down to a low baseline (rather than a large fixed instance) during idle periods — well suited to unpredictable, intermittent workloads.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c33ffc94-724a-46c7-b860-e940a1d69b33', 'd5517e04-dbf1-44bf-9144-ab2033d7f190', 1, 'RDS Multi-AZ, since Multi-AZ automatically scales compute capacity up and down based on real-time load.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('a854bf90-3908-4007-9234-625a5e50c4ea', 'd5517e04-dbf1-44bf-9144-ab2033d7f190', 2, 'A fixed, manually-sized Aurora instance is always the only available Aurora capacity option, with no automatic scaling alternative.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('39fbdd42-9fb9-41a1-b638-ff153024095c', 'd5517e04-dbf1-44bf-9144-ab2033d7f190', 3, 'S3 Intelligent-Tiering, since Intelligent-Tiering provides Aurora''s automatic compute-capacity scaling.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('4313a2f9-36f7-4db5-9ab6-35510035b93e', '5e3e85dd-8de7-4437-af4b-10919f914670', 0, 'AWS Transit Gateway, a central hub that each VPC (and on-premises connection, via Direct Connect or VPN) connects to individually, letting Transit Gateway route traffic between all attached networks through simplified, centrally-managed routing tables — avoiding the need to maintain a separate point-to-point VPC peering connection between every single pair of VPCs (which grows quadratically as VPC count increases).');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('c6f830b4-9641-4c0f-9891-67e2dadc259e', '5e3e85dd-8de7-4437-af4b-10919f914670', 1, 'VPC Peering itself already automatically consolidates into a hub-and-spoke model once more than 3 VPCs are involved, with no additional service needed.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0990c713-2f27-475a-ab1d-3791dad13a01', '5e3e85dd-8de7-4437-af4b-10919f914670', 2, 'Amazon Route 53, since Route 53''s core function is consolidating dozens of individual VPC peering connections into one hub.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('27782f28-c94e-420e-854b-ee3ed4286f1a', '5e3e85dd-8de7-4437-af4b-10919f914670', 3, 'This kind of multi-VPC connectivity consolidation is not achievable through any AWS networking service.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('e89bece0-0ce2-40db-8b09-1664f9c2c852', '5789bc2b-a71a-4687-b3d8-41656c07a58a', 0, 'Fargate Spot, which runs eligible ECS tasks on spare Fargate capacity at a significant discount compared to standard Fargate pricing, in exchange for the same fundamental trade-off as EC2 Spot — AWS can reclaim (interrupt) the capacity with notice, making it appropriate specifically for fault-tolerant, interruptible workloads rather than tasks requiring guaranteed continuous availability.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('115f7ef0-b590-4800-b5d6-dd1eeee37559', '5789bc2b-a71a-4687-b3d8-41656c07a58a', 1, 'Standard Fargate pricing already provides the same discount level as EC2 Spot Instances by default, with no separate Spot option needed or available for Fargate.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6fab0444-b62a-4c62-85ca-04fbd63e0f21', '5789bc2b-a71a-4687-b3d8-41656c07a58a', 2, 'Fargate has no discounted, interruptible pricing option comparable to EC2 Spot under any configuration.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('35501167-210f-4daf-866b-a28fc52d2e3c', '5789bc2b-a71a-4687-b3d8-41656c07a58a', 3, 'AWS Direct Connect provides the discounted, interruptible Fargate pricing tier described.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('fc394a63-57b7-4b90-b718-4eb56ea6bbff', '88ad02f9-6cc3-4fef-aa4a-08c0105c10b3', 0, 'AWS Budgets Actions, which can be configured to automatically execute a real response when a budget threshold is breached — such as applying a specific IAM policy or SCP, or targeting an EC2/RDS instance for a stop action — going beyond Budgets'' basic alert-only notifications into genuine automated remediation.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('5d8a3f18-bafb-4661-8d35-9bee4928a221', '88ad02f9-6cc3-4fef-aa4a-08c0105c10b3', 1, 'AWS Budgets can only ever send email/SNS notifications and has no capability to trigger any automated corrective action under any configuration.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('3d3f41b5-f328-40df-be03-86b7e91ac682', '88ad02f9-6cc3-4fef-aa4a-08c0105c10b3', 2, 'Amazon Inspector, since Inspector''s core function is automatically applying IAM policy restrictions when a budget threshold is exceeded.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('29a43445-9d2d-4925-83d0-c3d0aa24e627', '88ad02f9-6cc3-4fef-aa4a-08c0105c10b3', 3, 'AWS Trusted Advisor, since Trusted Advisor automatically applies restrictive IAM policies once a spending threshold is reached.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('991e75fc-67d4-4865-9505-128d480941fc', 'a42b6806-864f-4609-8ee1-3dbedc648e91', 0, 'S3 One Zone-IA, which stores data in a single Availability Zone (rather than the 3+ AZs most other S3 storage classes use), offering a lower cost than S3 Standard-IA specifically in exchange for reduced resilience — the data does not survive the loss of that one specific AZ, making it appropriate only for easily recreatable or non-critical infrequently-accessed data.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6809eb04-1ddc-4f14-ac67-1cd12498bba6', 'a42b6806-864f-4609-8ee1-3dbedc648e91', 1, 'S3 Standard, since S3 Standard is the storage class that intentionally stores data in only one Availability Zone for cost savings.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('925cd2be-f16e-47aa-a268-df96f43d380f', 'a42b6806-864f-4609-8ee1-3dbedc648e91', 2, 'S3 Glacier Deep Archive, since Deep Archive stores data in a single AZ specifically to enable millisecond retrieval at the lowest cost.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('bc03122d-cb51-48f9-b6ff-ee7f1be56135', 'a42b6806-864f-4609-8ee1-3dbedc648e91', 3, 'Every S3 storage class provides identical multi-AZ resilience with no single-AZ option available at any price point.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ef28686d-764b-40d5-b20d-107a815a09b0', '236b8eea-3449-466c-983e-92340390744c', 0, 'RDS Performance Insights, a database performance monitoring feature providing detailed visibility into database load, top SQL queries by load contribution, and wait events — giving much deeper, database-specific insight than general compute utilization metrics alone to inform whether an instance is genuinely over- or under-provisioned for its actual query workload.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('ff4c46aa-34c2-436e-a4aa-e7d8a74bf79f', '236b8eea-3449-466c-983e-92340390744c', 1, 'RDS Multi-AZ, since Multi-AZ''s core function is providing detailed database query performance and wait-event analysis.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('0cce5877-a88a-4b28-86d0-7a38682e92da', '236b8eea-3449-466c-983e-92340390744c', 2, 'AWS Direct Connect, since Direct Connect provides database-specific query and wait-event performance analysis for RDS.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('8823d891-56af-45f9-bac4-dd8d18bdbf15', '236b8eea-3449-466c-983e-92340390744c', 3, 'No AWS feature provides database-specific performance insight beyond general CPU/memory/network metrics.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
INSERT INTO questions (id, paper_id, sort_order, question_text)
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('cb7313fb-9766-40f7-99a2-201e01b6972e', '4c91c213-46b7-44a6-b756-81b8721749f9', 0, 'Cost Explorer''s forecasting feature, which uses historical cost and usage data to predict likely future spending, providing a data-driven projection rather than a purely backward-looking historical view alone, directly supporting more informed budget planning.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('2306dbcb-ddd8-4aad-aa90-cb369a58d680', '4c91c213-46b7-44a6-b756-81b8721749f9', 1, 'Cost Explorer can only display historical, already-incurred spending and has no forward-looking forecasting capability of any kind.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('179277c4-7c90-49cc-8647-69a22e9815fe', '4c91c213-46b7-44a6-b756-81b8721749f9', 2, 'AWS Config, since Config''s core function is forecasting future AWS spending based on historical trends.');
INSERT INTO question_options (id, question_id, sort_order, option_text) VALUES ('6da5097a-fcbf-424c-8a52-caca1f06fdf3', '4c91c213-46b7-44a6-b756-81b8721749f9', 3, 'Amazon GuardDuty, since GuardDuty provides spending forecasts based on historical cost and usage data.');
INSERT INTO question_answers (question_id, correct_option_id, explanation)
